 class Task implements Callable<Object> {
    int n,k;
    char[] s;


    public Task(int n, int k, char[] s) {
        super();
        this.n = n;
        this.k = k;
        this.s = s;
    }


    @Override
    public Object call() throws Exception {
        int count = 0;
        for(int i=0;i<=n-k;i++) {
            if (s[i] == '-') {
                for(int j=0;j<k;j++) {
                    if (s[i+j] == '-') {
                        s[i+j] = '+';
                    }else{
                        s[i+j] = '-';
                    }
                }
                count++;
            }
        }
        for(int i=0;i<n;i++) {
            if (s[i] == '-') {
                return "IMPOSSIBLE";
            }
        }
        return count;
    }

 }

