                 String divisor = null;
                 BigInteger value = new BigInteger(new String(ans), d);
                 for (int n = 2; n <= 100; n++) {
                     if (value.equals(BigInteger.valueOf(n))) continue;
                     if (value.mod(BigInteger.valueOf(n)).equals(BigInteger.ZERO)) {
                         divisor = n + " ";
                         break;
                     }
                 }
                 if (divisor == null) {
                     continue outer;
                 }
                 out += divisor;
             }
             System.out.printf("%s%n", out);
             i += 1;
         }
     }
