     static class TaskC {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 public int n, m;
                 public char[][] grid;

                 public void read(InputReader in) {
                     n = in.nextInt();
                     m = in.nextInt();
                     grid = new char[n][m];
                     for (int i = 0; i < n; i++) {
                         grid[i] = in.next().toCharArray();
                     }
                 }

                 public String ans;
                 public char[][] agrid;

                 public int hort(int a, int b) {
                     return 4 * (a * m + b) + 0;
                 }

                 public int horf(int a, int b) {
                     return 4 * (a * m + b) + 1;
                 }

                 public int vert(int a, int b) {
                     return 4 * (a * m + b) + 2;
                 }

                 public int verf(int a, int b) {
                     return 4 * (a * m + b) + 3;
                 }

                 public int top(int a, int b) {
                     if (grid[a][b] == '/') {
                         return vert(a, b);
                     } else if (grid[a][b] == '\\') {
                         return hort(a, b);
                     } else {
                         return vert(a, b);
                     }
                 }

                 public int bottom(int a, int b) {
                     if (grid[a][b] == '/') {
                         return hort(a, b);
                     } else if (grid[a][b] == '\\') {
                         return vert(a, b);
                     } else {
                         return vert(a, b);
                     }
                 }

                 public int left(int a, int b) {
                     if (grid[a][b] == '/') {
                         return vert(a, b);
                     } else if (grid[a][b] == '\\') {
                         return vert(a, b);
                     } else {
                         return hort(a, b);
                     }
                 }

                 public int right(int a, int b) {
                     if (grid[a][b] == '/') {
                         return hort(a, b);
                     } else if (grid[a][b] == '\\') {
                         return hort(a, b);
                     } else {
                         return hort(a, b);
                     }
                 }

                 public int ci = -1, cj = -1;
                 public boolean ch;
                 public int[][] pss;
                 public boolean[][] dd;
                 public int[][] count;

                 public boolean bad(int a, int b, int dir) {
                     if (a < 0 || a >= n || b < 0 || b >= m) return false;
                     if (grid[a][b] == '-' || grid[a][b] == '|') return true;
                     if (grid[a][b] == '#') return false;
                     if (grid[a][b] == '/') dir ^= 3;
                     if (grid[a][b] == '\\') dir ^= 1;
                     return bad(a + dx[dir], b + dy[dir], dir);
                 }

                 public void getNeigh(int a, int b, int dir) {
                     if (a < 0 || a >= n || b < 0 || b >= m) return;
                     if (grid[a][b] == '#') return;
                     if (pss[a][b] != -1) {
                         int p = pss[a][b] / m, q = pss[a][b] % m;
                         if (ch) {
                             graph[horf(ci, cj)].add(vert(p, q));
                             graph[verf(p, q)].add(hort(ci, cj));
                         } else {
                             graph[verf(ci, cj)].add(hort(p, q));
                             graph[horf(p, q)].add(vert(ci, cj));
                         }
                     }
                     pss[a][b] = ci * m + cj;
                     count[a][b]++;
                     dd[a][b] = ch;
                     if (grid[a][b] == '/') dir ^= 1;
                     if (grid[a][b] == '\\') dir ^= 3;
                     getNeigh(a + dx[dir], b + dy[dir], dir);
                 }

                 public List<Integer>[] graph;

                 public int[] dx = {-1, 0, 1, 0}, dy = {0, -1, 0, 1};

                 public void solve() {
                     int nnodes = 2 * n * m;
                     pss = new int[n][m];
                     count = new int[n][m];
                     dd = new boolean[n][m];
                     for (int[] x : pss) Arrays.fill(x, -1);
                     graph = LUtils.genArrayList(nnodes * 2);
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < m; j++) {
                             if (grid[i][j] == '#') continue;
                             if (grid[i][j] == '-' || grid[i][j] == '|') {
                                 graph[hort(i, j)].add(verf(i, j));
                                 graph[horf(i, j)].add(vert(i, j));
                                 graph[vert(i, j)].add(horf(i, j));
                                 graph[verf(i, j)].add(hort(i, j));
                             }








                         }
                     }
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < m; j++) {
                             if (grid[i][j] == '-' || grid[i][j] == '|') {
                                 ci = i;
                                 cj = j;
                                 ch = true;
                                 if (bad(i, j + 1, 3) || bad(i, j - 1, 1)) graph[hort(i, j)].add(horf(i, j));
                                 else {
                                     getNeigh(i, j + 1, 3);
                                     getNeigh(i, j - 1, 1);
                                 }
                                 ch = false;
                                 if (bad(i + 1, j, 2) || bad(i - 1, j, 0)) graph[vert(i, j)].add(verf(i, j));
                                 else {
                                     getNeigh(i + 1, j, 2);
                                     getNeigh(i - 1, j, 0);
                                 }
                             }
                         }
                     }
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < m; j++) {
                             if (grid[i][j] != '.') continue;
                             if (count[i][j] == 0) {
                                 ans = "IMPOSSIBLE";
                                 return;
                             } else if (count[i][j] == 1) {
                                 int p = pss[i][j] / m, q = pss[i][j] % m;
                                 if (dd[i][j]) graph[horf(p, q)].add(hort(p, q));
                                 else graph[verf(p, q)].add(vert(p, q));
                             }
                         }
                     }
                     boolean[] x = Sat2.solve2Sat(graph);
                     if (x == null) {
                         ans = "IMPOSSIBLE";
                         return;
                     }
                     ans = "POSSIBLE";
                     agrid = new char[n][m];
                     for (int i = 0; i < n; i++) {
                         for (int j = 0; j < m; j++) {
                             if (grid[i][j] == '-' || grid[i][j] == '|') {
                                 int v = 2 * (i * m + j);
                                 if (x[v]) agrid[i][j] = '-';
                                 else agrid[i][j] = '|';
                             } else {
                                 agrid[i][j] = grid[i][j];
                             }
                         }
                     }
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.println("Case #" + testNumber + ": " + ans);
                     if (ans.equals("POSSIBLE")) {
                         for (char[] x : agrid) out.println(new String(x));
                     }
                 }
             }, 16);
         }

