     static class Sat2 {
         static void dfs1(List<Integer>[] graph, boolean[] used, List<Integer> order, int u) {
             used[u] = true;
             for (int v : graph[u])
                 if (!used[v])
                     dfs1(graph, used, order, v);
             order.add(u);
         }

         static void dfs2(List<Integer>[] reverseGraph, int[] comp, int u, int color) {
             comp[u] = color;
             for (int v : reverseGraph[u])
                 if (comp[v] == -1)
                     dfs2(reverseGraph, comp, v, color);
         }

         public static boolean[] solve2Sat(List<Integer>[] graph) {
             int n = graph.length;
             boolean[] used = new boolean[n];
             List<Integer> order = new ArrayList<>();
             for (int i = 0; i < n; ++i)
                 if (!used[i])
                     dfs1(graph, used, order, i);

             List<Integer>[] reverseGraph = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);
             for (int i = 0; i < n; i++)
                 for (int j : graph[i])
                     reverseGraph[j].add(i);

             int[] comp = new int[n];
             Arrays.fill(comp, -1);
             for (int i = 0, color = 0; i < n; ++i) {
                 int u = order.get(n - i - 1);
                 if (comp[u] == -1)
                     dfs2(reverseGraph, comp, u, color++);
             }

             for (int i = 0; i < n; ++i)
                 if (comp[i] == comp[i ^ 1])
                     return null;

             boolean[] res = new boolean[n / 2];
             for (int i = 0; i < n; i += 2)
                 res[i / 2] = comp[i] > comp[i ^ 1];
             return res;
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (this.numChars == -1) {
                 throw new InputMismatchException();
             } else {
                 if (this.curChar >= this.numChars) {
                     this.curChar = 0;

                     try {
                         this.numChars = this.stream.read(this.buf);
                     } catch (IOException var2) {
                         throw new InputMismatchException();
                     }

                     if (this.numChars <= 0) {
                         return -1;
                     }
                 }

                 return this.buf[this.curChar++];
             }
         }

         public int nextInt() {
             int c;
             for (c = this.read(); isSpaceChar(c); c = this.read()) {
                 ;
             }

             byte sgn = 1;
             if (c == 45) {
                 sgn = -1;
                 c = this.read();
             }

             int res = 0;

             while (c >= 48 && c <= 57) {
                 res *= 10;
                 res += c - 48;
                 c = this.read();
                 if (isSpaceChar(c)) {
                     return res * sgn;
                 }
             }

             throw new InputMismatchException();
         }

         public String next() {
             int c;
             while (isSpaceChar(c = this.read())) {
                 ;
             }

             StringBuilder result = new StringBuilder();
             result.appendCodePoint(c);

             while (!isSpaceChar(c = this.read())) {
                 result.appendCodePoint(c);
             }

             return result.toString();
         }

         public static boolean isSpaceChar(int c) {
             return c == 32 || c == 10 || c == 13 || c == 9 || c == -1;
         }

     }

     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.nextInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static class LUtils {
         public static <E> List<E>[] genArrayList(int size) {
             return Stream.generate(ArrayList::new).limit(size).toArray(List[]::new);
         }

     }

     static interface Task {
         public void read(InputReader in);

         public void solve();

         public void write(OutputWriter out, int testNumber);

     }
 }

