     for (int pref = 0; pref <= n; pref++) {
       boolean ok = true;
       for (int j = 0; j < pref; j++) {
         if (a1[j] != a2[j] && a1[j] != '?' && a2[j] != '?') {
           ok = false;
           break;
         }
       }
       if (!ok) continue;
       char[] x1 = Arrays.copyOf(a1, n);
       char[] x2 = Arrays.copyOf(a2, n);
       for (int i = 0; i < pref; i++) {
         if (a1[i] == '?' && a2[i] == '?') {
           x1[i] = '0';
           x2[i] = '0';
         } else if (a1[i] == '?') {
           x1[i] = a2[i];
         } else if (a2[i] == '?') {
