public class C_Qual_GCJ2016 {

     public static long MOD = 1000000007;
     static int count;

     public static void main(String[] args) throws FileNotFoundException {
         PrintWriter out = new PrintWriter(new FileOutputStream(new File(
                 "output.txt")));

         Scanner in = new Scanner();
         int t = in.nextInt();
         for (int z = 0; z < t; z++) {
             int n = in.nextInt();
             int j = in.nextInt();
             out.println("Case #" + (z + 1) + ":");
             count = j;
             char[] cur = new char[n];
             cur[n - 1] = '1';
             cal(n - 2, 1, 1, cur, out);
         }
         out.close();
     }

     public static void cal(int index, int bit, int mod, char[] cur, PrintWriter out) {
         if (count == 0) {
             return;
         }
         if (index == 0) {
             cur[index] = '1';
             mod = (mod * 2 + 1) % 3;
             if (mod == 0 && bit % 2 == 1) {
                 ArrayList<Integer> list = new ArrayList();


                 for (int i = 2; i <= 10; i++) {
                     if (i % 2 == 0) {
                         int result = -1;
                         for (int j = 3; j < 200; j += 2) {
                             if(check(cur, i, j)){
                                 result = j;
                                 break;
                             }
                         }
                         if (result != -1) {
                             list.add(result);
                         }else{
                             return;
                         }

                     } else {                        
                         list.add(2);
                     }
                 }
                 out.print(new String(cur));
                 for(int i : list){
                     out.print(" " + i);
                 }
                 out.println();
                 count--;
             }
             return;
         }
         cur[index] = '0';
         cal(index - 1, bit, (mod * 2) % 3, cur, out);
         cur[index] = '1';
         cal(index - 1, bit + 1, (mod * 2 + 1) % 3, cur, out);

     }

     public static boolean check(char[] cur, int base, int mod) {
         int tmp = 0;
         for (int i = cur.length - 1; i >= 0; i--) {
             if (cur[i] == '1') {
                 tmp = ((tmp * base) % mod + 1) % mod;
             } else {
                 tmp = (tmp * base) % mod;
             }
         }
         return tmp == 0;
     }

     public static int[] KMP(String val) {
         int i = 0;
         int j = -1;
         int[] result = new int[val.length() + 1];
         result[0] = -1;
         while (i < val.length()) {
             while (j >= 0 && val.charAt(j) != val.charAt(i)) {
                 j = result[j];
             }
             j++;
             i++;
             result[i] = j;
         }
         return result;

     }

     public static boolean nextPer(int[] data) {
         int i = data.length - 1;
         while (i > 0 && data[i] < data[i - 1]) {
             i--;
         }
         if (i == 0) {
             return false;
         }
         int j = data.length - 1;
         while (data[j] < data[i - 1]) {
             j--;
         }
         int temp = data[i - 1];
         data[i - 1] = data[j];
         data[j] = temp;
         Arrays.sort(data, i, data.length);
         return true;
     }

     public static int digit(long n) {
         int result = 0;
         while (n > 0) {
             n /= 10;
             result++;
         }
         return result;
     }

     public static double dist(long a, long b, long x, long y) {
         double val = (b - a) * (b - a) + (x - y) * (x - y);
         val = Math.sqrt(val);
         double other = x * x + a * a;
         other = Math.sqrt(other);
         return val + other;

     }

     public static class Point implements Comparable<Point> {

         int x, y;

         public Point(int start, int end) {
             this.x = start;
             this.y = end;
         }

         @Override
         public int hashCode() {
             int hash = 5;
             hash = 47 * hash + this.x;
             hash = 47 * hash + this.y;
             return hash;
         }

         @Override
         public boolean equals(Object obj) {
             if (obj == null) {
                 return false;
             }
             if (getClass() != obj.getClass()) {
                 return false;
             }
             final Point other = (Point) obj;
             if (this.x != other.x) {
                 return false;
             }
             if (this.y != other.y) {
                 return false;
             }
             return true;
         }

         @Override
         public int compareTo(Point o) {
             return Integer.compare(x, o.x);
         }
     }

     public static class FT {

         long[] data;

         FT(int n) {
             data = new long[n];
         }

         public void update(int index, long value) {
             while (index < data.length) {
                 data[index] += value;
                 index += (index & (-index));
             }
         }

         public long get(int index) {
             long result = 0;
             while (index > 0) {
                 result += data[index];
                 index -= (index & (-index));
             }
             return result;

         }
     }

     public static long gcd(long a, long b) {
         if (b == 0) {
             return a;
         }
         return gcd(b, a % b);
     }

     public static long pow(long a, long b, long MOD) {
         if (b == 0) {
             return 1;
         }
         if (b == 1) {
             return a;
         }
         long val = pow(a, b / 2, MOD);
         if (b % 2 == 0) {
             return val * val % MOD;
         } else {
             return val * (val * a % MOD) % MOD;

         }
     }

     static class Scanner {

         BufferedReader br;
         StringTokenizer st;

         public Scanner() throws FileNotFoundException {


               br = new BufferedReader(new InputStreamReader(new FileInputStream(new File("C-small-attempt1.in"))));
         }

         public String next() {

             while (st == null || !st.hasMoreTokens()) {
                 try {
                     st = new StringTokenizer(br.readLine());
                 } catch (Exception e) {
                     throw new RuntimeException();
                 }
             }
             return st.nextToken();
         }

         public long nextLong() {
             return Long.parseLong(next());
         }

         public int nextInt() {
             return Integer.parseInt(next());
         }

         public double nextDouble() {
             return Double.parseDouble(next());
         }

         public String nextLine() {
             st = null;
             try {
                 return br.readLine();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }

         public boolean endLine() {
             try {
                 String next = br.readLine();
                 while (next != null && next.trim().isEmpty()) {
                     next = br.readLine();
                 }
                 if (next == null) {
                     return true;
                 }
                 st = new StringTokenizer(next);
                 return st.hasMoreTokens();
             } catch (Exception e) {
                 throw new RuntimeException();
             }
         }
     }
 }
