         int first = s.charAt(0)-'A';
         for (int i=1;i<s.length();i++) {
             int v = s.charAt(i)-'A';
             if (v >= first) {
                 first = v;
                 res.insert(0, s.charAt(i));
             }
             else {
                 res.append(s.charAt(i));
             }
         }
         return res.toString();
     }

     public static void debug(Object...args) {
         System.out.println(Arrays.deepToString(args));
     }
 }
