    ArrayList<Integer>[] g;

    class Segment {
        int st, en;
        int num;

        public Segment(int st, int en, int num) {
            super();
            this.st = st;
            this.en = en;
            this.num = num;
        }
    }

    ArrayList<Segment> segs;
    int[] s, m;

    void dfs(int v, int min, int max) {
        min = Math.min(min, s[v]);
        max = Math.max(max, s[v]);
        segs.add(new Segment(min, max, v));
        for (int u : g[v])
            dfs(u, min, max);
    }

    public void solve() throws IOException {
        segs = new ArrayList<>();
        int n = in.nextInt(), d = in.nextInt();
        g = new ArrayList[n];
        for (int i = 0; i < n; i++)
            g[i] = new ArrayList<>();
        s = new int[n];
        m = new int[n];
        s[0] = in.nextInt();
        int as = in.nextInt(), cs = in.nextInt(), rs = in.nextInt();
        for (int i = 1; i < n; i++) {
            s[i] = (int) ((1L * s[i - 1] * as + cs) % rs);
        }
        m[0] = in.nextInt();
        int am = in.nextInt(), cm = in.nextInt(), rm = in.nextInt();
        for (int i = 1; i < n; i++) {
            m[i] = (int) ((1L * m[i - 1] * am + cm) % rm);
            g[m[i] % i].add(i);
        }
        dfs(0, s[0], s[0]);
        Collections.sort(segs, new Comparator<Segment>() {

            @Override
            public int compare(Segment o1, Segment o2) {
                return Integer.compare(o1.en, o2.en);
            }
        });
        TreeSet<Segment> now = new TreeSet<>(new Comparator<Segment>() {

            @Override
            public int compare(Segment o1, Segment o2) {
                if (o1.st != o2.st)
                    return Integer.compare(o1.st, o2.st);
                return Integer.compare(o1.num, o2.num);
            }
        });
        int ans = 0;
        for (int i = 0; i < segs.size();) {
            int cur = segs.get(i).en;
            while (i < segs.size() && segs.get(i).en == cur) {
                Segment seg = segs.get(i);
                now.add(seg);
                i++;
            }
            while (now.size() > 0) {
                Segment seg = now.first();
                if (seg.st < cur - d)
                    now.remove(seg);
                else
                    break;
            }
            ans = Math.max(ans, now.size());
        }
        out.println(ans);
    }

