             int N = in.nextInt();
             String answer;
             if (N == 0) {
                 answer = "INSOMNIA";
             } else {
                 answer = Long.toString(solve(N));
             }
             out.println("Case #"+(t+1)+": " +answer);
         }

         out.close();
     }

     private static long solve(int N) {
         int seenCount = 0;
         boolean[] seen = new boolean[10];
         long factor = 0;
         while (seenCount < 10) {
             factor++;
             long number = factor*N;
             while (number != 0) {
                 int digit = (int)(number%10);
                 number /= 10;
                 if (!seen[digit]) {
                     seenCount++;
                     seen[digit] = true;
                 }
             }
         }
         return factor*N;
     }

 }
