public class C {
    FastScanner in = new FastScanner(System.in);
    PrintWriter out = new PrintWriter(System.out);

    BigInteger convert(long x, int base) {
        String s = Long.toBinaryString(x);
        BigInteger bbase = new BigInteger(String.valueOf(base));
        BigInteger res = BigInteger.ZERO;
        for (int i = 0, p = s.length() - 1; i < s.length(); i++, p--) {
            if (s.charAt(i) != '0') {
                res = res.add(bbase.pow(p));
            }
        }
        return res;
    }

    int[] calc(long x) {
        final int MAX = 1000;
        int[] res = new int[11];
        for (int base = 2; base <= 10; base++) {
            BigInteger b = convert(x, base);
            for (int i = 2; i <= MAX; i++) {
                BigInteger div = new BigInteger(Integer.toString(i));
                if (b.mod(div).intValue() == 0) {
                    res[base] = i;
                    break;
                } else if (i == MAX) {
                    return null;
                }
            }
        }
        return res;
    }

    public void run() {
        int T = in.nextInt();
        for (int caseN = 1; caseN <= T; caseN++) {
            int N = in.nextInt();
            int J = in.nextInt();

            ArrayList<String> res = new ArrayList<String>();

            for (long i = (1L << (N-1)) + 1; i < (1L << N); i += 2) {
                int[] divs = calc(i);
                if (divs == null) continue;

                String next = Long.toBinaryString(i) + " ";
                for (int j = 2; j <= 10; j++) {
                    next += divs[j];
                    if (j != 10) next += " ";
                }
                res.add(next);
                if (res.size() == J) break;
            }

            if (res.size() != J) {
                throw new RuntimeException();
            }
            out.println("Case #" + caseN + ": ");
            for (String s : res)
                out.println(s);
        }
        out.close();
    }

    public static void main(String[] args) {
        new C().run();
    }

