public class C {
    FastScanner in;
    PrintWriter out;

    Random rnd = new Random(123);

    String gen(int len) {
        char[] s = new char[len];
        for (int i = 0; i < len; i++) {
            s[i] = rnd.nextBoolean() ? '1' : '0';
        }
        s[0] = s[len - 1] = '1';
        return new String(s);
    }

    long[] check(String s) {
        long[] all = new long[11];
        for (int base = 2; base <= 10; base++) {
            long z = 1, val = 0;
            for (int i = s.length() - 1; i >= 0; i--) {
                if (s.charAt(i) == '1') {
                    val += z;
                }
                z *= base;
            }
            if (BigInteger.valueOf(val).isProbablePrime(100)) {
                return null;
            }
            for (long k = 2; k * 1L * k <= val; k++) {
                if (val % k == 0) {
                    all[base] = k;
                    break;
                }
            }
            if (all[base] == 0) {
                throw new AssertionError();
            }
        }
        return all;
    }

    void solve() {
        int tc = in.nextInt();
        for (int t = 0; t < tc; t++) {
            out.println("Case #" + (t + 1) + ":");
            int n = in.nextInt();
            int cnt = in.nextInt();
            HashMap<String, long[]> was = new HashMap<>();
            HashSet<String> bad = new HashSet<>();
            while (was.size() < cnt) {
                String s = gen(n);
                if (was.containsKey(s)) {
                    continue;
                }
                if (bad.contains(s)) {
                    continue;
                }
                long[] check = check(s);
                if (check == null) {
                    bad.add(s);
                } else {
                    was.put(s, check);
                }
                System.err.println("current size is = " + was.size());
            }
            for (Map.Entry<String, long[]> entry : was.entrySet()) {
                out.print(entry.getKey());
                for (int i = 2; i <= 10; i++) {
                    out.print(" " + entry.getValue()[i]);
                }
                out.println();
            }
            System.err.println((t + 1) + "/" + tc + " done");
        }
    }

    void run() {
        try {
            in = new FastScanner(new File("C.in"));
            out = new PrintWriter(new File("C.out"));

            solve();

            out.close();
        } catch (FileNotFoundException e) {
            e.printStackTrace();
        }
    }

    void runIO() {
        in = new FastScanner(System.in);
        out = new PrintWriter(System.out);

        solve();

        out.close();
    }

