    class P implements Comparable<P>{
        char name;
        int cnt;
        P(int n, int c){
            name = (char)('A'+n);
            cnt=c;
        }
        @Override
        public int compareTo(P arg0) {
            return arg0.cnt-cnt;
        }
    }
    public String solve() {
        int n = scan.nextInt();
        P[]A = new P[n];
        int tot=0;
        for(int i=0;i<n;i++){
            A[i]=new P(i,scan.nextInt());
            tot+=A[i].cnt;
        }
        StringBuffer sb = new StringBuffer();
        while(true) {
            Arrays.sort(A);
            if(A[0].cnt==0)break;
            if(tot%2==1) {
                A[0].cnt--;
                sb.append(A[0].name+" ");
                tot--;
            } else if(A[0].cnt==A[1].cnt){
                A[0].cnt--;
                A[1].cnt--;
                sb.append(A[0].name+""+A[1].name+" ");
            } else {
                A[0].cnt--;
                A[0].cnt--;
                sb.append(A[0].name+""+A[0].name+" ");  
            }
        }
        return sb.toString();
    }


