 class TaskB {
     public void solve(int testNumber, InputReader in, PrintWriter out) {
         out.print("Case #" + testNumber + ": ");
         int R = in.nextInt();
         int C = in.nextInt();
         int N = in.nextInt();
         if (N <= 1) {
             out.println("0");
             return;
         }
         int ans = 10000000;
         for (int i = 2; i < 1<<(R*C); i++) {
             int n = Integer.bitCount(i);
             if (n == N) {
                 int unhappy = 0;
                 for (int r = 0; r < R; r++) {
                     for (int c = 0; c < C; c++) {
                         int v = r*C+c;
                         if ((i & (1<<v)) > 0) {
                             if (r < R-1 && (i & 1<<(v+C)) > 0) {
                                 unhappy++;
                             }
                             if (c < C-1 && (i & 1<<(v+1)) > 0) {
                                 unhappy++;
                             }
                         }
                     }
                 }
                 ans = Math.min(ans,unhappy);
             }
         }
         out.println(ans);
     }
 }

