            int n = stdin.nextInt();

            double maxReach = 0;
            for (int i=0; i<n; i++) {
                int mark = stdin.nextInt();
                int speed = stdin.nextInt();
                double reach = (double)(d-mark)/speed;
                maxReach = Math.max(maxReach, reach);
