        T = readInt();

        for (int t = 1; t <= T; t++) {
            N = readInt();
            K = readInt();

            U = readDouble();
            prob = new double[N];
            for (int i = 0; i < N; i++)
                prob[i] = readDouble();

            double lo = 0;
            double hi = 1;
            while (hi - lo >= EPS) {
                double mid = (hi + lo) / 2;
                double total = 0;
                for (int i = 0; i < N; i++)
                    if (prob[i] < mid)
                        total += mid - prob[i];
                if (total > U)
                    hi = mid;
                else
                    lo = mid;
            }
            double ans = 1;
            for (int i = 0; i < N; i++) {
                if (prob[i] < lo) {
                    prob[i] = lo;
                }
                ans *= prob[i];
            }
            out.printf("Case #%d: %f\n", t, ans);
        }

        out.close();
    }

