    public static boolean tryassign(int n,int[] RYB,int[] assignment)
    {
        System.out.println(n);
        if((n>1)&&(assignment[n-1]==assignment[n]))
            return false;
        if(n==assignment.length-1)
        {
            if(assignment[0]!=assignment[n])
            return true;
            else
            return false;
        }
        for(int j=0;j<3;j++)
        {
            if(RYB[j]>0)
            {
            assignment[n] = j;
            RYB[j]--;
            if(tryassign(n+1,RYB,assignment))
            {
                return true;
            }
            RYB[j]++;
            }
        }
        return false;
    }

    public static int[] ord(int[] RYB)
    {
        int[] order = new int[3];
        if(RYB[0]>=Math.max(RYB[1],RYB[2]))
        {
            order[0] = 0;
            if(RYB[1]>=RYB[2])
            {
                order[1] = 1;
                order[2] = 2;
            }else
            {
                order[1] = 2;
                order[2] = 1;
            }
            return order;
        }
        if(RYB[1]>=Math.max(RYB[0],RYB[2]))
        {
            order[0] = 1;
            if(RYB[0]>=RYB[2])
            {
                order[1] = 0;
                order[2] = 2;
            }else
            {
                order[1] = 2;
                order[2] = 0;
            }
            return order;
        }
        if(RYB[2]>=Math.max(RYB[1],RYB[0]))
        {
            order[0] = 2;
            if(RYB[1]>=RYB[0])
            {
                order[1] = 1;
                order[2] = 0;
            }else
            {
                order[1] = 0;
                order[2] = 1;
            }
        }
        return order;
    }
 }
