             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified())
                     toRun = candidate;
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("c.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskC solver = new TaskC();
         int testCount = Integer.parseInt(in.next());
         for (int i = 1; i <= testCount; i++)
             solver.solve(i, in, out);
         out.close();
     }

     static class TaskC {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printFormat("Case #%d: ", testNumber);
             int n = in.readInt();
             String[] a = new String[n];
             String[] b = new String[n];
             for (int i = 0; i < n; i++) {
                 a[i] = in.readString();
                 b[i] = in.readString();
             }
             int maxFakes = 0;
             for (int mask = 0; mask < (1 << n); mask++) {
                 int curFakes = Integer.bitCount(mask);
                 List<String> x = new ArrayList<>();
                 List<String> y = new ArrayList<>();
                 List<String> fx = new ArrayList<>();
                 List<String> fy = new ArrayList<>();
                 for (int i = 0; i < n; i++) {
                     if ((mask & (1 << i)) == 0) {
                         x.add(a[i]);
                         y.add(b[i]);
                     } else {
                         fx.add(a[i]);
                         fy.add(b[i]);
                     }
                 }
                 boolean ok = true;
                 for (int fi = 0; fi < fx.size(); fi++) {
                     String s1 = fx.get(fi);
                     String s2 = fy.get(fi);
                     boolean found1 = false;
                     boolean found2 = false;
                     for (int i = 0; i < x.size(); i++) {
                         if (s1.equals(x.get(i))) found1 = true;
                     }
                     for (int i = 0; i < x.size(); i++) {
                         if (s2.equals(y.get(i))) found2 = true;
                     }
                     if (found1 && found2) {
                         x.add(s1);
                         y.add(s2);
                     } else {
                         ok = false;
                         break;
                     }
                 }
                 if (ok) {
                     maxFakes = Math.max(maxFakes, curFakes);
                 }
             }
             out.printLine(maxFakes);
         }

     }

     static class InputReader {
         private InputStream stream;
         private byte[] buf = new byte[1024];
         private int curChar;
         private int numChars;
         private SpaceCharFilter filter;

         public InputReader(InputStream stream) {
             this.stream = stream;
         }

         public int read() {
             if (numChars == -1)
                 throw new InputMismatchException();
             if (curChar >= numChars) {
                 curChar = 0;
                 try {
                     numChars = stream.read(buf);
                 } catch (IOException e) {
                     throw new InputMismatchException();
                 }
                 if (numChars <= 0)
                     return -1;
             }
             return buf[curChar++];
         }

         public int readInt() {
             int c = read();
             while (isSpaceChar(c))
                 c = read();
             int sgn = 1;
             if (c == '-') {
                 sgn = -1;
                 c = read();
             }
             int res = 0;
             do {
                 if (c < '0' || c > '9')
                     throw new InputMismatchException();
                 res *= 10;
                 res += c - '0';
                 c = read();
             } while (!isSpaceChar(c));
             return res * sgn;
         }

         public String readString() {
             int c = read();
             while (isSpaceChar(c))
                 c = read();
             StringBuilder res = new StringBuilder();
             do {
                 if (Character.isValidCodePoint(c))
                     res.appendCodePoint(c);
                 c = read();
             } while (!isSpaceChar(c));
             return res.toString();
         }

         public boolean isSpaceChar(int c) {
             if (filter != null)
                 return filter.isSpaceChar(c);
             return isWhitespace(c);
         }

         public static boolean isWhitespace(int c) {
             return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
         }

         public String next() {
             return readString();
         }

         public interface SpaceCharFilter {
             public boolean isSpaceChar(int ch);

         }

     }

     static class OutputWriter {
         private final PrintWriter writer;

         public OutputWriter(OutputStream outputStream) {
             writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
         }

         public OutputWriter(Writer writer) {
             this.writer = new PrintWriter(writer);
         }

         public void printFormat(String format, Object... objects) {
             writer.printf(format, objects);
         }

         public void close() {
             writer.close();
         }

         public void printLine(int i) {
             writer.println(i);
         }

     }
 }

