public class Main {
     public static void main(String[] args) {
         Locale.setDefault(Locale.US);
         InputStream inputStream;
         try {
             final String regex = "A-(small|large).*[.]in";
             File directory = new File(".");
             File[] candidates = directory.listFiles(new FilenameFilter() {
                 public boolean accept(File dir, String name) {
                     return name.matches(regex);
                 }
             });
             File toRun = null;
             for (File candidate : candidates) {
                 if (toRun == null || candidate.lastModified() > toRun.lastModified())
                     toRun = candidate;
             }
             inputStream = new FileInputStream(toRun);
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         OutputStream outputStream;
         try {
             outputStream = new FileOutputStream("a.out");
         } catch (IOException e) {
             throw new RuntimeException(e);
         }
         InputReader in = new InputReader(inputStream);
         OutputWriter out = new OutputWriter(outputStream);
         TaskA solver = new TaskA();
         int testCount = Integer.parseInt(in.next());
         for (int i = 1; i <= testCount; i++)
             solver.solve(i, in, out);
         out.close();
     }

     static class TaskA {
         static final char[] v = "RPS".toCharArray();

         public void solve(int testNumber, InputReader in, OutputWriter out) {
             out.printFormat("Case #%d: ", testNumber);
             int n = in.readInt();
             int R = in.readInt();
             int P = in.readInt();
             int S = in.readInt();
             char[] a = new char[1 << n];
             List<Integer> have = new ArrayList<>();
             List<String> winStrings = new ArrayList<>();
             int[] cnt = new int[256];
             for (char winnerChar : v) {
                 have.clear();
                 have.add(0);
                 Arrays.fill(a, (char) 0);
                 a[0] = winnerChar;
                 cnt['R'] = R;
                 cnt['S'] = S;
                 cnt['P'] = P;
                 cnt[winnerChar]--;
                 for (int d = (1 << n) / 2; d >= 1; d /= 2) {
                     int sz = have.size();
                     for (int i = 0; i < sz; i++) {
                         int pos = have.get(i);
                         int loserPos = pos ^ d;
                         char loserChar = loserFor(a[pos]);
                         a[loserPos] = loserChar;
                         have.add(loserPos);
                         cnt[loserChar]--;
                     }
                 }
                 if (cnt['R'] == 0 && cnt['S'] == 0 && cnt['P'] == 0) {
                     winStrings.add(new String(a));
                 }
             }
             if (winStrings.isEmpty()) {
                 out.printLine("IMPOSSIBLE");
             } else {
                 String min = null;
                 for (String s : winStrings) {
                     String t = process(s);
                     if (min == null || t.compareTo(min) < 0) {
                         min = t;
                     }
                 }
                 out.printLine(min);
             }
         }

         private String process(String s) {
             int n = s.length();
             if ((n & (n - 1)) != 0) {
                 throw new IllegalArgumentException();
             }
             StringBuilder sb = new StringBuilder();
             for (int d = 1; d < n; d *= 2) {
                 sb.setLength(0);
                 for (int i = 0; i < n; i += 2 * d) {
                     String a = s.substring(i, i + d);
                     String b = s.substring(i + d, i + 2 * d);
                     if (a.compareTo(b) > 0) {
                         String t = a;
                         a = b;
                         b = t;
                     }
                     sb.append(a);
                     sb.append(b);
                 }
                 s = sb.toString();
             }
             return s;
         }

         private char loserFor(char c) {
             if (c == 'R') return 'S';
             if (c == 'S') return 'P';
             if (c == 'P') return 'R';
             throw new IllegalArgumentException();
         }

     }

     static class InputReader {
