                        temp.append("R");
                        Unicron[colors.R]--;
                    }
                    temp.append("G");
                    temp.append("R");
                    Unicron[colors.R]--;
                }
                if (temp.length() != 0)
                    R.add(temp.toString());
                for (int a = 0; a < Unicron[colors.R]; a++) {
                    R.add("R");
                }


