            int prev = (j+(i-1))%i;
            int next = (j+1)%i;
            int people = list.get(j).intValue();
            int prevpeople = list.get(prev).intValue();
            int nextpeople = list.get(next).intValue();
            if (table[people] == prevpeople || table[people]==nextpeople) {
            } else {
                checkFlag=false;
                break;
            }
            }
            if (checkFlag) {
            if (i>maxN) {
                maxN = i;
