                        ps[j][k]++;
                        sj[k][i]++;
                        sb.append((i+1) + " " + (j+1) + " " + (k+1) + "\n");
                        cnt++;
                    }
                }
            }
        }

        return "" + cnt + "\n" + sb.toString().trim();
