                return o2.intValue() - o1.intValue();
            }
        });
        que.add(N);
        for(int i = 0; i < K; i++){
            int n = que.poll();
            n--;
            int a = n /2;
            int b = a;
            if(n % 2 == 1){
                a++;
            }
            que.add(a);
            que.add(b);
            if(i == K-1){
                println(a + " " + b);
            }
        }
    }


