       int max = 1000000;
       int[] res = new int[max + 1];
       Arrays.fill(res, -1);
       res[1] = 1;
       Queue<Integer> q = new LinkedList<Integer>();
       q.add(1);
       while (!q.isEmpty()) {
         int a = q.poll();
         int n = a + 1;
         if (n <= max && res[n] == -1) {
           res[n] = res[a] + 1;
           q.add(n);
         }
         n = inv(a);
         if (n <= max && res[n] == -1) {
           res[n] = res[a] + 1;
           q.add(n);
         }
       }
       for (int test = 1; test <= tests; test++) {

         out.println("Case #" + test + ": " + res[in.nextInt()]);
       }

       out.close();
     } catch (Exception e) {
       throw new RuntimeException(e);
     }
   }

