    public void solve() throws Exception {
        int B = iread(), N = iread();
        int[] M = new int[B];
        for (int i = 0; i < B; i++)
            M[i] = iread();
        long L = -1, R = 100000000000001L;
        while (L + 1 < R) {
            long place = B;
            long med = (L + R) / 2;
            for (int i = 0; i < B; i++)
                place += med / M[i];
            if (place >= N)
                R = med;
            else
                L = med;
        }

        for (int i = 0; i < B; i++)
            N -= 1 + (R - 1) / M[i];
        for (int i = 0; i < B; i++) {
            if (R % M[i] == 0) {
                if (N > 1)
                    N--;
                else {
                    out.write((i + 1) + "");
                    return;
                }
            }
        }
    }

