     static class TaskB {
         public void solve(int testNumber, InputReader in, OutputWriter out) {
             Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
                 int ac;
                 int aj;
                 int[] c;
                 int[] d;
                 int[] j;
                 int[] k;


                 public void read(InputReader in) {
                     ac = in.readInt();
                     aj = in.readInt();
                     c = new int[ac];
                     d = new int[ac];
                     j = new int[aj];
                     k = new int[aj];
                     IOUtils.readIntArrays(in, c, d);
                     IOUtils.readIntArrays(in, j, k);
                 }

                 int answer;


                 public void solve() {
                     int[] start = new int[ac + aj];
                     int[] end = new int[ac + aj];
                     int[] type = new int[ac + aj];
                     System.arraycopy(c, 0, start, 0, ac);
                     System.arraycopy(d, 0, end, 0, ac);
                     System.arraycopy(j, 0, start, ac, aj);
                     System.arraycopy(k, 0, end, ac, aj);
                     Arrays.fill(type, ac, ac + aj, 1);
                     int first = 0;
                     int second = 0;
                     IntList firstBreaks = new IntArrayList();
                     IntList secondBreaks = new IntArrayList();
                     ArrayUtils.orderBy(start, end, type);
                     for (int i = 1; i < ac + aj; i++) {
                         if (type[i] == 0) {
                             first += end[i] - start[i];
                             if (type[i - 1] == 0) {
                                 first += start[i] - end[i - 1];
                                 firstBreaks.add(start[i] - end[i - 1]);
                             } else {
                                 answer++;
                             }
                         } else {
                             second += end[i] - start[i];
                             if (type[i - 1] == 1) {
                                 second += start[i] - end[i - 1];
                                 secondBreaks.add(start[i] - end[i - 1]);
                             } else {
                                 answer++;
                             }
                         }
                     }
                     if (type[0] == 0) {
                         first += end[0] - start[0];
                         if (type[ac + aj - 1] == 0) {
                             first += start[0] - end[ac + aj - 1] + 24 * 60;
                             firstBreaks.add(start[0] - end[ac + aj - 1] + 24 * 60);
                         } else {
                             answer++;
                         }
                     } else {
                         second += end[0] - start[0];
                         if (type[ac + aj - 1] == 1) {
                             second += start[0] - end[ac + aj - 1] + 24 * 60;
                             secondBreaks.add(start[0] - end[ac + aj - 1] + 24 * 60);
                         } else {
                             answer++;
                         }
                     }
                     if (first <= 720 && second <= 720) {
                         return;
                     }
                     if (second > 720) {
                         first = second;
                         firstBreaks = secondBreaks;
                     }
                     firstBreaks.sort(IntComparator.REVERSE);
                     for (int i : firstBreaks) {
                         first -= i;
                         answer += 2;
                         if (first <= 720) {
                             return;
                         }
                     }
                 }


                 public void write(OutputWriter out, int testNumber) {
                     out.printLine("Case #" + testNumber + ":", answer);
                 }
             }, 4);
