     }

     static class ArrayUtils {
         public static int[] range(int from, int to) {
             return Range.range(from, to).toArray();
         }

         public static int[] createOrder(int size) {
             return range(0, size);
         }

         public static int[] sort(int[] array, IntComparator comparator) {
             return sort(array, 0, array.length, comparator);
         }

         public static int[] sort(int[] array, int from, int to, IntComparator comparator) {
             if (from == 0 && to == array.length) {
                 new IntArray(array).sort(comparator);
             } else {
                 new IntArray(array).subList(from, to).sort(comparator);
             }
             return array;
         }

         public static int[] order(final int[] array) {
             return sort(createOrder(array.length), new IntComparator() {
                 public int compare(int first, int second) {
                     if (array[first] < array[second]) {
                         return -1;
                     }
                     if (array[first] > array[second]) {
                         return 1;
                     }
                     return 0;
                 }
             });
         }

         public static void orderBy(int[] base, int[]... arrays) {
             int[] order = ArrayUtils.order(base);
             order(order, base);
             for (int[] array : arrays) {
                 order(order, array);
             }
         }

         public static void order(int[] order, int[] array) {
             int[] tempInt = new int[order.length];
             for (int i = 0; i < order.length; i++) {
                 tempInt[i] = array[order[i]];
             }
             System.arraycopy(tempInt, 0, array, 0, array.length);
         }

     }

     static class Scheduler {
         private final AtomicInteger testsRemaining;
         private final AtomicInteger threadsRemaining;

         public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
             try {
                 testsRemaining = new AtomicInteger(in.readInt());
                 threadsRemaining = new AtomicInteger(numParallel);
                 Task[] tasks = new Task[testsRemaining.get()];
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i] = factory.newTask();
                 }
                 for (Task task : tasks) {
                     task.read(in);
                     new Thread(() -> {
                         boolean freeThread = false;
                         synchronized (this) {
                             do {
                                 try {
                                     wait(10);
                                 } catch (InterruptedException ignored) {
                                 }
                                 if (threadsRemaining.get() != 0) {
                                     synchronized (threadsRemaining) {
                                         if (threadsRemaining.get() != 0) {
                                             threadsRemaining.decrementAndGet();
                                             freeThread = true;
                                         }
                                     }
                                 }
                             } while (!freeThread);
                         }
                         task.solve();
                         System.err.println(testsRemaining.decrementAndGet());
                         threadsRemaining.incrementAndGet();
                     }).start();
                 }
                 synchronized (this) {
                     while (testsRemaining.get() > 0) {
                         wait(10);
                     }
                 }
                 for (int i = 0; i < tasks.length; i++) {
                     tasks[i].write(out, i + 1);
                 }
             } catch (InterruptedException e) {
                 throw new RuntimeException(e);
             }
         }

     }

     static class Range {
         public static IntList range(int from, int to) {
             int[] result = new int[Math.abs(from - to)];
             int current = from;
             if (from <= to) {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current++;
                 }
             } else {
                 for (int i = 0; i < result.length; i++) {
                     result[i] = current--;
                 }
             }
             return new IntArray(result);
         }

     }

     static interface Task {
         public void read(InputReader in);

         public void solve();

         public void write(OutputWriter out, int testNumber);

     }

     static abstract class IntAbstractStream implements IntStream {

         public String toString() {
             StringBuilder builder = new StringBuilder();
             boolean first = true;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 if (first) {
                     first = false;
                 } else {
                     builder.append(' ');
                 }
                 builder.append(it.value());
             }
             return builder.toString();
         }


         public boolean equals(Object o) {
             if (!(o instanceof IntStream)) {
                 return false;
             }
             IntStream c = (IntStream) o;
             IntIterator it = intIterator();
             IntIterator jt = c.intIterator();
             while (it.isValid() && jt.isValid()) {
                 if (it.value() != jt.value()) {
                     return false;
                 }
                 it.advance();
                 jt.advance();
             }
             return !it.isValid() && !jt.isValid();
         }


         public int hashCode() {
             int result = 0;
             for (IntIterator it = intIterator(); it.isValid(); it.advance()) {
                 result *= 31;
                 result += it.value();
             }
             return result;
         }

