 class TaskD {
     public void solve(int testNumber, InputReader in, OutputWriter out) {
         Scheduler scheduler = new Scheduler(in, out, () -> new Task() {
             int count;
             long[] values;
             long[] frequencies;
             long[] answer;

             public void read(InputReader in) {
                 count = in.readInt();
                 values = IOUtils.readLongArray(in, count);
                 frequencies = IOUtils.readLongArray(in, count);
             }

             public void solve() {
                 long sum = 0;
                 for (long i : frequencies) {
                     sum += i;
                 }
                 int size = Long.bitCount(sum - 1);
                 answer = new long[size];
                 long[] curFrequencies = new long[count];
                 curFrequencies[0] = 1;
                 int at = 0;
                 for (int i = 0; i < count; i++) {
                     while (curFrequencies[i] != frequencies[i]) {
                         answer[at++] = values[i] - values[0];
                         long delta = values[i] - values[0];
                         int k = count - 1;
                         for (int j = count - 1; j >= 0; j--) {
                             while (k > 0 && values[j] - values[k] < delta) {
                                 k--;
                             }
                             if (values[j] - values[k] == delta) {
                                 curFrequencies[j] += curFrequencies[k];
                             }
                         }
                     }
                 }
             }

             public void write(OutputWriter out, int testNumber) {
                 out.print("Case #" + testNumber + ": ");
                 out.printLine(answer);
             }
         }, 4);
     }
 }

 class InputReader {

    private InputStream stream;
    private byte[] buf = new byte[1024];
    private int curChar;
    private int numChars;
    private SpaceCharFilter filter;

    public InputReader(InputStream stream) {
        this.stream = stream;
    }

    public int read() {
        if (numChars == -1)
            throw new InputMismatchException();
        if (curChar >= numChars) {
            curChar = 0;
            try {
                numChars = stream.read(buf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (numChars <= 0)
                return -1;
        }
        return buf[curChar++];
    }

    public int readInt() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        int res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public long readLong() {
        int c = read();
        while (isSpaceChar(c))
            c = read();
        int sgn = 1;
        if (c == '-') {
            sgn = -1;
            c = read();
        }
        long res = 0;
        do {
            if (c < '0' || c > '9')
                throw new InputMismatchException();
            res *= 10;
            res += c - '0';
            c = read();
        } while (!isSpaceChar(c));
        return res * sgn;
    }

    public boolean isSpaceChar(int c) {
        if (filter != null)
            return filter.isSpaceChar(c);
        return isWhitespace(c);
    }

    public static boolean isWhitespace(int c) {
        return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
    }

    public interface SpaceCharFilter {
        public boolean isSpaceChar(int ch);
    }
 }

 class OutputWriter {
    private final PrintWriter writer;

    public OutputWriter(OutputStream outputStream) {
        writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
    }

    public void print(Object...objects) {
        for (int i = 0; i < objects.length; i++) {
            if (i != 0)
                writer.print(' ');
            writer.print(objects[i]);
        }
    }

    public void print(long[] array) {
         for (int i = 0; i < array.length; i++) {
             if (i != 0)
                 writer.print(' ');
             writer.print(array[i]);
         }
     }

    public void printLine(long[] array) {
         print(array);
         writer.println();
     }

    public void close() {
        writer.close();
    }

 }

 class Scheduler {
    private final AtomicInteger testsRemaining;
    private final AtomicInteger threadsRemaining;

    public Scheduler(InputReader in, OutputWriter out, TaskFactory factory, int numParallel) {
        try {
            testsRemaining = new AtomicInteger(in.readInt());
            threadsRemaining = new AtomicInteger(numParallel);
            Task[] tasks = new Task[testsRemaining.get()];
            for (int i = 0; i < tasks.length; i++) {
                tasks[i] = factory.newTask();
            }
            for (Task task : tasks) {
                task.read(in);
                new Thread(() -> {
                    boolean freeThread = false;
                    synchronized (this) {
                        do {
                            try {
                                wait(10);
                            } catch (InterruptedException ignored) {
                            }
                            if (threadsRemaining.get() != 0) {
                                synchronized (threadsRemaining) {
                                    if (threadsRemaining.get() != 0) {
                                        threadsRemaining.decrementAndGet();
                                        freeThread = true;
                                    }
                                }
                            }
                        } while (!freeThread);
                    }
                    task.solve();
                    System.err.println(testsRemaining.decrementAndGet());
                    threadsRemaining.incrementAndGet();
                }).start();
            }
            synchronized (this) {
                while (testsRemaining.get() > 0) {
                    wait(10);
                }
            }
            for (int i = 0; i < tasks.length; i++) {
                tasks[i].write(out, i + 1);
            }
        } catch (InterruptedException e) {
            throw new RuntimeException(e);
        }
    }
 }

 interface Task {
    public void read(InputReader in);
    public void solve();
    public void write(OutputWriter out, int testNumber);
 }

 class IOUtils {

