                switch(p[i][j])
                {
                case '<':
                    dx=0;
                    dy=-1;
                    break;
                case '>':
                    dx=0;
                    dy=1;
                    break;
                case '^':
                    dx=-1;
                    dy=0;
                    break;
                case 'v':
                    dx=1;
                    dy=0;
                    break;
                }
                do
                {
                    x+=dx;
                    y+=dy;
                    if(x>=0&&x<R&&y>=0&&y<C&&id[x][y]>-1)break;
                }while(x>=0&&x<R&&y>=0&&y<C);
                if(x>=0&&x<R&&y>=0&&y<C)
                    uf.join(id[x][y], id[i][j]);
