        if(!poss(id))return "IMPOSSIBLE";
        HashSet <Integer> miss = new HashSet<Integer>();

        for(int i=0; i<R; i++)
        {
            for(int j=0; j<C; j++)
            {
                if(p[i][j]=='.')continue;
                int cl = uf.getP(id[i][j]);
                if(miss.contains(cl))continue;
                int x=i, y=j;
                int dx=-1000, dy=-1000;
                switch(p[i][j])
                {
                case '<':
                    dx=0;
                    dy=-1;
                    break;
                case '>':
                    dx=0;
                    dy=1;
                    break;
                case '^':
                    dx=-1;
                    dy=0;
                    break;
