                }while(x>=0&&x<R&&y>=0&&y<C);
                if(x>=0&&x<R&&y>=0&&y<C)
                {

                }
                else
                {
                    miss.add(cl);
                }
            }
        }
        int ret=miss.size();
        return ""+ret;
    }

    private boolean poss(int [] [] p)
    {
        int N=p.length;
        int M=p[0].length;
        for(int i=0; i<N; i++)
        {
            for(int j=0; j<M; j++)
            {
                if(p[i][j]==-1)continue;
                int cnt=0;
                for(int x=0; x<N; x++)
                    if(p[x][j]>-1)cnt++;
                for(int x=0; x<M; x++)
                    if(p[i][x]>-1)cnt++;
                if(cnt==2)return false;
            }
        }
        return true;
    }

    private class UF
    {
        int [] p;
        int [] s;
        int N;
        int cnt;
        UF(int N)
        {
            this.N=N;
            s = new int[N];
            p = new int[N];
            for(int i=0; i<N; i++)
            {
                p[i]=i;
                s[i]=1;
            }
            cnt=N;
        }

        public void join(int a, int b)
        {

            int x=getP(a);
            int y=getP(b);

            if(x==y)return;
            if(s[x]>s[y])
            {
                int t=x;
                x=y;
                y=t;
            }
            p[x]=p[y];
            s[y]+=s[x];
            cnt--;
        }

        public int getP(int a)
        {
            if(p[a]==a)return a;
            return p[a]=getP(p[a]);
        }

        public int getC(int x)
        {
            return s[getP(x)];
        }
    }

 }


