        if (x == 0 || !seen.add(x)) {
            return;
        }
        int[] count = new int[n + 1];
        count[0] = n;
        for (int i = n; i >= 1; i--) {
            count[i] = x % 10;
            x /= 10;
            count[0] -= count[i];
        }
        if (count[0] < 0) {
            return;
        }
        search(0, count);
